effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:
 //////////////////////////
 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

     const float PI = 3.1415926535897932;

       float col(vec2 coord,float time)
       {
         float delta_theta = 2.0 * PI / angle;
         float col = 0.0;
         float theta = 0.0;
         for (int i = 0; i < int(steps); i++)
         {
           vec2 adjc = coord;
           theta = delta_theta*float(i);
           adjc.x += cos(theta)*time*speed + time * speed_x;
           adjc.y -= sin(theta)*time*speed - time * speed_y;
           col = col + cos( (adjc.x*cos(theta) - adjc.y*sin(theta))*frequency)*intensity;
         }

         return cos(col);
       }
 //////////////////////////
     void main() {
     if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);
     float time = autop? PROGRESS + (acTime*SPEEED) : PROGRESS;

     vec2 TanRyu;
     TanRyu = acScreenNorm.st; 
     TanRyu /= scale;
     TanRyu *= rot2m((-180.0)*0.0174533);
     TanRyu += vec2((0.0+position.x), (0.0-position.y))*vec2(-1.,1.)/500.;

     /////////////////////////

 	vec4 fragColor;

     vec2 p = vec2(-TanRyu.x,TanRyu.y);
     // vec2 p = TanRyu;
     vec2 c1 = p;
     vec2 c2 = p;
     float cc1 = col(c1,time);

     c2.x += iResolution.x/delta;
     float dx = emboss*(cc1-col(c2,time))/delta;

     c2.x = p.x;
     c2.y += iResolution.y/delta;
     float dy = emboss*(cc1-col(c2,time))/delta;

     c1.x += dx*2.;
     c1.y = -(c1.y+dy*2.);

     float alphaa = 1.+dot(dx,dy)*gain;

     float ddx = dx - reflectionCutOff;
     float ddy = dy - reflectionCutOff;
     if (ddx > 0. && ddy > 0.)
     	alphaa = pow(alpha, ddx*ddy*(reflectionIntensity*1000.0));

     vec4 col = texture2DCv(inputImg.texture,c1)*(alphaa);
     fragColor = col;

 	    vec4 factor = mix(texColorX,fragColor,1.0);

 	gl_FragColor = mix(texColor, factor, alpha);
       }
     }
